/-- Bounding hyperplane is a face of the closed halfspace cone. -/
lemma isFaceOf_closedHalfspace_hyperplane (a : E) :
    IsFaceOf (closedHalfspace a 0) {x : E | ⟪a, x⟫ = 0}

lemma isHyperplaneCellComplex_closedHalfspace_zero_mono {As : Set E} {a : E}
    (ha : a ∈ As) :
    IsHyperplaneCellComplex (coneArrangement As) (closedHalfspace a 0)

lemma openPositive_two (a b : E) :
    (closedHalfspace a 0)ᶜ ∩ (closedHalfspace b 0)ᶜ =
      {x : E | 0 < ⟪a, x⟫ ∧ 0 < ⟪b, x⟫}

lemma eulerCharacteristic_eq_sum_cellsBelow {A : Set (Hyperplane E)} {S : Set E}
    (hA : A.Finite) :
    eulerCharacteristic A S = ∑ C ∈ cellsBelow A S hA, cellSign C

/-- Stated Paulson targets (not claimed in Results.lean until proved in full). -/
def EulerPolyhedralConeGoal : String :=
  "faceEulerSum S (finrank) = 0 for full-dim proper polyhedral cones"

/-- Normals that vanish identically on a cell. -/
def coneCellZeros (As : Set E) (C : Set E) : Set E :=
  {a ∈ As | ∀ x ∈ C, ⟪a, x⟫ = 0}

/-- Normals that are strictly negative on a cell. -/
def coneCellNegs (As : Set E) (C : Set E) : Set E :=
  {a ∈ As | ∀ x ∈ C, ⟪a, x⟫ < 0}

/-- Explicit sign-pattern description of a cone-arrangement cell inside the cone. -/
lemma coneCell_eq_sign_pattern {As : Set E} {C : Set E}
    (hC : IsHyperplaneCell (coneArrangement As) C)
    (hsub : C ⊆ ⋂ a ∈ As, closedHalfspace a 0) :
    C = {x : E | (∀ a ∈ coneCellNegs As C, ⟪a, x⟫ < 0) ∧
      (∀ a ∈ coneCellZeros As C, ⟪a, x⟫ = 0)}

lemma cone_face_eq_closed_pattern {As : Set E} {C : Set E}
    (hC : IsHyperplaneCell (coneArrangement As) C)
    (hsub : C ⊆ ⋂ a ∈ As, closedHalfspace a 0) :
    (⋂ a ∈ As, closedHalfspace a 0) ∩ ⋂ a ∈ coneCellZeros As C, {x : E | ⟪a, x⟫ = 0} =
      {x : E | (∀ a ∈ coneCellNegs As C, ⟪a, x⟫ ≤ 0) ∧
        (∀ a ∈ coneCellZeros As C, ⟪a, x⟫ = 0)}

/-- Normals that vanish identically on a face. -/
def coneFaceZeros (As : Set E) (F : Set E) : Set E :=
  {a ∈ As | ∀ x ∈ F, ⟪a, x⟫ = 0}

/-- Open sign pattern cut out by a face's active (non-vanishing) normals. -/
def coneFaceOpenPattern (As : Set E) (F : Set E) : Set E :=
  {x : E | (∀ a ∈ As \ coneFaceZeros As F, ⟪a, x⟫ < 0) ∧
    (∀ a ∈ coneFaceZeros As F, ⟪a, x⟫ = 0)}

/-- Nonempty faces of a polyhedral cone equal the cone cut by the face's vanishing normals. -/
theorem face_eq_polyhedralCone_inter_zeros {As : Set E} (hAs : As.Finite) {F : Set E}
    (hF : IsFaceOf (⋂ a ∈ As, closedHalfspace a 0) F) (hne : F.Nonempty)
    [FiniteDimensional ℝ E] :
    F = (⋂ a ∈ As, closedHalfspace a 0) ∩
      ⋂ a ∈ coneFaceZeros As F, {x : E | ⟪a, x⟫ = 0}

lemma intrinsicInterior_subset_coneFaceOpenPattern {As : Set E} {F : Set E}
    (hF : IsFaceOf (⋂ a ∈ As, closedHalfspace a 0) F) :
    intrinsicInterior ℝ F ⊆ coneFaceOpenPattern As F

lemma height_pos_of_mem_conicHull {p : Set E} {i : E}
    (hp : ∀ x ∈ p, ⟪i, x⟫ = 1) {y : E}
    (hy : y ∈ conicHull p) (hne : y ≠ 0) : 0 < ⟪i, y⟫

lemma zero_not_mem_affineSpan_of_height {s : Set E} {i : E}
    (hs : ∀ x ∈ s, ⟪i, x⟫ = 1) :
    (0 : E) ∉ affineSpan ℝ s

lemma injOn_conicHull_faces {p : Set E} {i : E}
    (hht : ∀ F, IsFaceOf p F → ∀ x ∈ F, ⟪i, x⟫ = 1) (d : ℕ) :
    InjOn conicHull {F : Set E | IsFaceOf p F ∧ affDim F = (d : ℤ)}

lemma inv_smul_mem_of_mem_conicHull {p : Set E} {i : E} {y : E}
    (hht : ∀ x ∈ p, ⟪i, x⟫ = 1) (hy : y ∈ conicHull p) (hne : y ≠ 0) :
    (⟪i, y⟫)⁻¹ • y ∈ p

lemma isFaceOf_conicHull_of_isFaceOf {p F : Set E} {i : E}
    (hht : ∀ x ∈ p, ⟪i, x⟫ = 1) (hF : IsFaceOf p F) :
    IsFaceOf (conicHull p) (conicHull F)

lemma affDim_insert_zero_of_not_mem [FiniteDimensional ℝ E] {F : Set E}
    (hne : F.Nonempty) (h0 : (0 : E) ∉ affineSpan ℝ F) :
    affDim (insert (0 : E) F) = affDim F + 1

lemma affDim_conicHull_eq [FiniteDimensional ℝ E] {F : Set E} {i : E}
    (hht : ∀ x ∈ F, ⟪i, x⟫ = 1) (hne : F.Nonempty) :
    affDim (conicHull F) = affDim F + 1

lemma isFaceOf_of_vadd (v : E) {S T : Set E}
    (h : IsFaceOf ((fun x => v + x) '' S) ((fun x => v + x) '' T)) :
    IsFaceOf S T

lemma height_one_of_mem_image {p : Set E} {y : ProdR (E := E)}
    (hy : y ∈ heightOneAffine '' p) :
    ⟪heightVec (E := E), y⟫ = 1

lemma eulerCharacteristic_of_finite {A : Set (Hyperplane E)} {S : Set E}
    (h : {C : Set E | IsHyperplaneCell A C ∧ C ⊆ S}.Finite) :
    eulerCharacteristic A S = ∑ C ∈ h.toFinset, cellSign C

/-- The cells of `A` contained in a cell `C` are exactly `{C}`. -/
lemma cells_subset_cell {A : Set (Hyperplane E)} {C : Set E}
    (hC : IsHyperplaneCell A C) :
    {D : Set E | IsHyperplaneCell A D ∧ D ⊆ C} = {C}

/-- Insert-cells inside an `A`-cell are the nonempty intersections with singleton cells. -/
lemma cells_insert_subset_of_cell {A : Set (Hyperplane E)} {a : E} {b : ℝ} {C : Set E}
    (hC : IsHyperplaneCell A C) :
    {D : Set E | IsHyperplaneCell (insert (a, b) A) D ∧ D ⊆ C} =
      {D | ∃ C1, IsHyperplaneCell {(a, b)} C1 ∧ D = C1 ∩ C ∧ (C1 ∩ C).Nonempty}

/-- Cells of `insert` inside a one-sided `A`-cell are exactly `{C}`. -/
lemma cells_insert_of_subset_side {A : Set (Hyperplane E)} {a : E} {b : ℝ} {C : Set E}
    (hC : IsHyperplaneCell A C) (ha : a ≠ 0)
    (hside : C ⊆ {x | ⟪a, x⟫ < b} ∨ C ⊆ {x | b < ⟪a, x⟫} ∨ C ⊆ {x | ⟪a, x⟫ = b}) :
    {D : Set E | IsHyperplaneCell (insert (a, b) A) D ∧ D ⊆ C} = {C}

/-- Nonnegative ray span of a set. Isabelle: `conic hull`. -/
def conicHull (s : Set E) : Set E :=
  {y | ∃ (c : ℝ) (x : E), 0 ≤ c ∧ x ∈ s ∧ y = c • x}

/-- Homogeneous normals for the cone over a height-1 slice of an H-rep polyhedron. -/
def homogenizeNormals (H : Set (Hyperplane E)) (i : E) : Set E :=
  (fun h : Hyperplane E => h.1 - h.2 • i) '' H ∪ {(-i)}

/-- A list of indices is *exposed* if it is exactly the set of maximisers of a functional. -/
def Exposed (S : List ℕ) : Prop :=
  ∃ a : R3, ∃ c : ℝ, (∀ u < D.n, ⟪a, D.P u⟫ ≤ c) ∧ ∀ u, u ∈ S ↔ u < D.n ∧ ⟪a, D.P u⟫ = c

theorem Exposed.hull_eq {S : List ℕ} {a : R3} {c : ℝ} (hle : ∀ u < D.n, ⟪a, D.P u⟫ ≤ c)
    (hS : ∀ u, u ∈ S ↔ u < D.n ∧ ⟪a, D.P u⟫ = c) :
    D.hull S = {x ∈ D.body | ⟪a, x⟫ = c}

lemma setOf_filter (L : List (List ℕ)) (p : List ℕ → Bool) (Q : Set R3 → Prop)
    (hQ : ∀ S ∈ L, Q (D.hull S) ↔ p S = true) :
    {x ∈ {y | ∃ S ∈ L, y = D.hull S} | Q x} = {x | ∃ S ∈ L.filter p, x = D.hull S}

lemma image_hull (hg : ∀ t < G.gens.length, G.genOk D t = true) {w : List ℕ}
    (hw : ∀ t ∈ w, t < G.gens.length) {S : List ℕ} (hS : ∀ u ∈ S, u < D.n) :
    G.iso w '' D.hull S = D.hull (S.map (G.permWord w))

/-- **Faces of polytopes are exposed.** -/
theorem IsPolytope.exposed_of_isFaceOf [FiniteDimensional ℝ E] {p : Set E}
    (hP : IsPolytope p) {F : Set E} (hF : IsFaceOf p F) (hne : F.Nonempty) :
    ∃ a : E, ∃ c : ℝ, (∀ x ∈ p, ⟪a, x⟫ ≤ c) ∧ F = {x ∈ p | ⟪a, x⟫ = c}

/-- Nonempty faces of a nontrivial closed halfspace cone are exactly the cone and its
bounding hyperplane. -/
lemma isFaceOf_closedHalfspace_zero_eq {a : E} (ha : a ≠ 0) {F : Set E}
    (hF : IsFaceOf (closedHalfspace a 0) F) (hne : F.Nonempty) :
    F = closedHalfspace a 0 ∨ F = {x : E | ⟪a, x⟫ = 0}

/-- Vertex subsets of size `m+1` indexing the combinatorial `m`-faces of an `n`-simplex. -/
def combinatorialFaces (n m : ℕ) : Finset (Finset (Fin (n + 1))) :=
  Finset.powersetCard (m + 1) (Finset.univ : Finset (Fin (n + 1)))

/-- Boundary cycle: consecutive Nat pairs plus the closing edge. -/
def fanBoundary (n : ℕ) (hn : 3 ≤ n) : Finset (Finset (Fin n)) :=
  (Finset.range (n - 1)).attach.image (fun k =>
    bEdge n k.1 (by have := Finset.mem_range.mp k.2; omega)) ∪
    {bEdgeClose n hn}

/-- Fan triangle `{0, i+1, i+2}` for `i < n-2`. -/
def fanTriangle (n : ℕ) (i : ℕ) (hi : i < n - 2) : Finset (Fin n) :=
  {v n 0 (by omega), v n (i + 1) (by omega), v n (i + 2) (by omega)}

def fanTriangles (n : ℕ) (_hn : 3 ≤ n) : Finset (Finset (Fin n)) :=
  (Finset.range (n - 2)).attach.image fun i =>
    fanTriangle n i.1 (Finset.mem_range.mp i.2)

/-- Fan diagonal `{0, i+2}` for `i < n-3`. -/
def fanDiagonal (n : ℕ) (i : ℕ) (hi : i < n - 3) : Finset (Fin n) :=
  {v n 0 (by omega), v n (i + 2) (by omega)}

def fanDiagonals (n : ℕ) (_hn : 3 ≤ n) : Finset (Finset (Fin n)) :=
  (Finset.range (n - 3)).attach.image fun i =>
    fanDiagonal n i.1 (Finset.mem_range.mp i.2)

lemma hyperplaneEquiv_trans {A : Set (Hyperplane E)} {x y z : E}
    (hxy : HyperplaneEquiv A x y) (hyz : HyperplaneEquiv A y z) :
    HyperplaneEquiv A x z

/-- `C` is a cell of arrangement `A` iff it is an equivalence class of
`HyperplaneEquiv A`. Isabelle: `hyperplane_cell`. -/
def IsHyperplaneCell (A : Set (Hyperplane E)) (C : Set E) : Prop :=
  ∃ x, C = {y | HyperplaneEquiv A x y}

lemma disjoint_isHyperplaneCell {A : Set (Hyperplane E)} {C₁ C₂ : Set E}
    (h₁ : IsHyperplaneCell A C₁) (h₂ : IsHyperplaneCell A C₂) (hne : C₁ ≠ C₂) :
    Disjoint C₁ C₂

/-- Cells of a singleton arrangement `{ (a,b) }` are the hyperplane or one of the
two open half-spaces. Isabelle: `hyperplane_cell_singleton_cases`. -/
lemma isHyperplaneCell_singleton_cases {a : E} {b : ℝ} {C : Set E}
    (h : IsHyperplaneCell {(a, b)} C) :
    C = {x | ⟪a, x⟫ = b} ∨ C = {x | ⟪a, x⟫ < b} ∨ C = {x | b < ⟪a, x⟫}

/-- Every cell is convex. Isabelle: `hyperplane_cell_convex`. -/
lemma isHyperplaneCell_convex {A : Set (Hyperplane E)} {C : Set E}
    (hC : IsHyperplaneCell A C) : Convex ℝ C

lemma isHyperplaneCellComplex_sUnion {A : Set (Hyperplane E)}
    {𝒞 : Set (Set E)} (h : ∀ S ∈ 𝒞, IsHyperplaneCellComplex A S) :
    IsHyperplaneCellComplex A (⋃₀ 𝒞)

lemma isHyperplaneCellComplex_union {A : Set (Hyperplane E)} {S T : Set E}
    (hS : IsHyperplaneCellComplex A S) (hT : IsHyperplaneCellComplex A T) :
    IsHyperplaneCellComplex A (S ∪ T)

lemma isHyperplaneCell_singleton_subset (a : E) (b : ℝ) :
    {C : Set E | IsHyperplaneCell {(a, b)} C} ⊆
      {{x | ⟪a, x⟫ = b}, {x | ⟪a, x⟫ < b}, {x | b < ⟪a, x⟫}}

lemma pairwise_disjoint_isHyperplaneCell {A : Set (Hyperplane E)} {Cs : Set (Set E)}
    (h : ∀ C ∈ Cs, IsHyperplaneCell A C) :
    Cs.Pairwise Disjoint

def FanDetPrimitive : Prop :=
  ∀ (i : ℕ) (hi : i < P.nVertices - 2),
    (fanTriangle P i hi).IsDetPrimitive

/-- Strictly positive oriented fan dets (nondegenerate + CCW). -/
def FanDetsPos : Prop :=
  ∀ (i : ℕ) (hi : i < P.nVertices - 2), 0 < fanDet P i hi

lemma edgeLatticePoints_ab_inter_bc
    (a b c : ℤ × ℤ) (hne : latticeDet a b c ≠ 0) :
    edgeLatticePoints a b ∩ edgeLatticePoints b c = {b}

lemma edgeLatticePoints_bc_inter_ca
    (a b c : ℤ × ℤ) (hne : latticeDet a b c ≠ 0) :
    edgeLatticePoints b c ∩ edgeLatticePoints c a = {c}

lemma edgeLatticePoints_ca_inter_ab
    (a b c : ℤ × ℤ) (hne : latticeDet a b c ≠ 0) :
    edgeLatticePoints c a ∩ edgeLatticePoints a b = {a}

/-- Half-open edge: lattice points on `vᵢ—vᵢ₊₁` excluding the left endpoint. -/
def openEdgeLattice (i : Fin P.nVertices) : Finset (ℤ × ℤ) :=
  (edgeLatticePoints (P.vertex i) (P.vertex (P.nextIdx i))).erase (P.vertex i)

/-- Fan triangle from apex `q` across edge `i`. -/
def interiorFanTriangle (q : ℤ × ℤ) (i : Fin P.nVertices) : Triangle :=
  ⟨q, P.vertex i, P.vertex (P.nextIdx i)⟩

/-- Strictly positive oriented interior-fan dets. -/
def InteriorFanDetsPos (q : ℤ × ℤ) : Prop :=
  ∀ i : Fin P.nVertices, 0 < interiorFanDet P q i

/-- Exactly two distinct interior lattice points (set form). -/
def TwoInterior (q r : ℤ × ℤ) : Prop :=
  q ≠ r ∧ P.interiorLatticePoints = ({q, r} : Set (ℤ × ℤ))

/-- The `i`-th vertex (requires `i < nVertices`). -/
def vertex (i : Fin P.nVertices) : ℤ × ℤ :=
  P.vertices.get i

/-- Lattice points lying in the convex hull of the vertices. -/
def latticePointsInConvexHull : Set (ℤ × ℤ) :=
  { p | toReal p ∈ P.convexHullRegion }

/-- Oriented 2×2 determinant of edge vectors from `a` to `b` and `a` to `c`. -/
def latticeDet (a b c : ℤ × ℤ) : ℤ :=
  (b.1 - a.1) * (c.2 - a.2) - (b.2 - a.2) * (c.1 - a.1)

/-- Shoelace area as a rational (`|det|/2`). Not yet identified with Haar measure. -/
def triangleShoelace (a b c : ℤ × ℤ) : ℚ :=
  (Int.natAbs (latticeDet a b c) : ℚ) / 2

/-- Lattice content of the edge from `p` to `q`. -/
def edgeGcd (p q : ℤ × ℤ) : ℕ :=
  Int.gcd (q.1 - p.1) (q.2 - p.2)

/-- Nonnegative integer barycentric coordinates with sum at most 1 (origin triangle). -/
def IsIntegerBarycentric (α β : ℤ) : Prop :=
  0 ≤ α ∧ 0 ≤ β ∧ α + β ≤ 1

def MemClosedTriangle (a b c p : ℤ × ℤ) : Prop :=
  ∃ α β γ : ℝ, 0 ≤ α ∧ 0 ≤ β ∧ 0 ≤ γ ∧ α + β + γ = 1 ∧
    α • toReal a + β • toReal b + γ • toReal c = toReal p

/-- Companion vector: if `gcd(u₁,u₂)=1` then `det(u, companion u)=1`. -/
def companion (u : ℤ × ℤ) : ℤ × ℤ :=
  (-Int.gcdB u.1 u.2, Int.gcdA u.1 u.2)

/-- Coefficient `α` of `u` in the `{u, companion u}` expansion of `v`. -/
def basisCoeffα (u v : ℤ × ℤ) : ℤ :=
  latticeDet (0, 0) v (companion u)

/-- Oriented companion so the `v`-coefficient is positive `|det|`. -/
def orientedCompanion (u v : ℤ × ℤ) : ℤ × ℤ :=
  if 0 < latticeDet (0, 0) u v then companion u else -companion u

/-- Same as `basisCoeffα`: flipping the companion absorbs the det sign, not `α`. -/
def orientedα (u v : ℤ × ℤ) : ℤ :=
  basisCoeffα u v

lemma latticeDet_orientedCompanion (u v : ℤ × ℤ) (h : Int.gcd u.1 u.2 = 1) :
    latticeDet (0, 0) u (orientedCompanion u v) =
      if 0 < latticeDet (0, 0) u v then (1 : ℤ) else (-1 : ℤ)

/-- A single affine halfspace has a finite presentation. -/
theorem IsPolyhedral.halfspace (f : E →ₗ[𝕜] 𝕜) (b : 𝕜) :
    IsPolyhedral 𝕜 {x | f x ≤ b}

/-- Intersections indexed by a finite type preserve finite presentations. -/
theorem IsPolyhedral.iInter {ι : Type*} [Finite ι] {s : ι → Set E}
    (hs : ∀ i, IsPolyhedral 𝕜 (s i)) : IsPolyhedral 𝕜 (⋂ i, s i)

/-- A hyperplane is the intersection of two opposite halfspaces. -/
theorem IsPolyhedral.hyperplane (f : E →ₗ[𝕜] 𝕜) (b : 𝕜) :
    IsPolyhedral 𝕜 {x | f x = b}

/-- Eliminate any finite number of auxiliary scalar coordinates. -/
theorem IsPolyhedral.project_fin (n : ℕ) {s : Set ((Fin n → 𝕜) × E)}
    (hs : IsPolyhedral 𝕜 s) :
    IsPolyhedral 𝕜 {x | ∃ w : Fin n → 𝕜, (w, x) ∈ s}

lemma not_mem_polygon_edge_of_mem_interior {p : ℤ × ℤ}
    (hp : p ∈ P.interiorLatticePoints) (i : Fin P.nVertices) :
    p ∉ edgeLatticePoints (P.edgePair i).1 (P.edgePair i).2

lemma concatFin_sum_map {β : Type} [AddCommMonoid β] (g : α → β) {n : ℕ}
    (f : Fin n → List α) :
    ((concatFin f).map g).sum = ∑ i, ((f i).map g).sum

/-- Each triangle has exactly three edges (2-subsets). -/
theorem card_powersetCard_two_of_mem_triangles {t : Finset α}
    (ht : t ∈ G.triangles) : (t.powersetCard 2).card = 3

/-- Incidence Finset: pairs `(t, e)` with `t` a triangle and `e ⊆ t` an edge. -/
def incidences : Finset (Finset α × Finset α) :=
  (G.triangles ×ˢ G.edges).filter fun p => p.2 ⊆ p.1

/-- Target Euler identity for a disk triangulation counting the outer face. -/
def PlanarDiskEulerCounts.eulerChar (C : PlanarDiskEulerCounts) : ℤ :=
  (C.V : ℤ) - C.E + C.F

/-- The five admissible Schläfli pairs. -/
def schlafliPairs : Finset (ℕ × ℕ) :=
  {(3, 3), (3, 4), (3, 5), (4, 3), (5, 3)}

/-- The set of faces of `p` of affine dimension `d`. Definitionally the set-builder
used by `euler_relation_convex_3polytope`. -/
def facesOfDim (p : Set E) (d : ℤ) : Set (Set E) :=
  {f : Set E | IsFaceOf p f ∧ affDim f = d}

/-- The simplex of all nonnegative weights with sum one is polyhedral. -/
theorem IsPolyhedral.weights (ι : Type*) [Fintype ι] :
    IsPolyhedral 𝕜 {w : ι → 𝕜 | (∀ i, 0 ≤ w i) ∧ ∑ i, w i = 1}

/-- A point is cut out by finitely many coordinate equalities, each expressed
as two closed halfspaces. -/
theorem IsPolyhedral.singleton_zero : IsPolyhedral 𝕜 {(0 : E)}

/-- A linear equality in a finite-dimensional codomain is polyhedral. -/
theorem IsPolyhedral.linear_eq_zero {F : Type*} [AddCommGroup F] [Module 𝕜 F]
    (f : F →ₗ[𝕜] E) : IsPolyhedral 𝕜 {x | f x = 0}

/-- Closed halfspace `{x | ⟪a, x⟫ ≤ b}`. -/
def closedHalfspace (a : E) (b : ℝ) : Set E :=
  {x | ⟪a, x⟫ ≤ b}

/-- Homogeneous H-description of a polyhedral cone. -/
def IsPolyhedralCone (S : Set E) : Prop :=
  ∃ As : Set E, As.Finite ∧ S = ⋂ a ∈ As, closedHalfspace a 0

/-- Arrangement associated to a homogeneous H-description: hyperplanes `(a, 0)`. -/
def coneArrangement (As : Set E) : Set (Hyperplane E) :=
  (fun a => (a, (0 : ℝ))) '' As

/-- Open positive orthant relative to normals `As` is a cell of the cone arrangement
(when nonempty). -/
lemma isHyperplaneCell_openPositive {As : Set E}
    (hne : ({x : E | ∀ a ∈ As, 0 < ⟪a, x⟫}).Nonempty) :
    IsHyperplaneCell (coneArrangement As) {x : E | ∀ a ∈ As, 0 < ⟪a, x⟫}

/-- **A supporting hyperplane cuts out a face.** If `⟪a, ·⟫ ≤ c` on a convex set `A`, then
`{x ∈ A | ⟪a, x⟫ = c}` is a face of `A`. -/
theorem isFaceOf_inter_hyperplane {A : Set E} (hA : Convex ℝ A) {a : E} {c : ℝ}
    (hle : ∀ x ∈ A, ⟪a, x⟫ ≤ c) :
    IsFaceOf A {x ∈ A | ⟪a, x⟫ = c}

/-- **The supported face of a V-polytope is the hull of the generators it contains.** -/
theorem inter_hyperplane_eq_convexHull_argmax {V : Set E} {a : E} {c : ℝ}
    (hle : ∀ v ∈ V, ⟪a, v⟫ ≤ c) :
    {x ∈ convexHull ℝ V | ⟪a, x⟫ = c} = convexHull ℝ {v ∈ V | ⟪a, v⟫ = c}

/-- A polyhedron is similar to **at most one** of the five constructed solids. -/
theorem platonicSolid_similar_unique {P : Set R3} {i j : Fin 5}
    (hi : Similar (platonicSolid i) P) (hj : Similar (platonicSolid j) P) : i = j

/-- A flag of `P`: a vertex inside an edge inside a facet. -/
def IsFlag (P : Set R3) (v e f : Set R3) : Prop :=
  v ∈ facesOfDim P 0 ∧ e ∈ facesOfDim P 1 ∧ f ∈ facesOfDim P 2 ∧ v ⊆ e ∧ e ⊆ f

/-- `Q` is similar to `P`: an isometry followed by a positive scaling about the origin. -/
def Similar (P Q : Set R3) : Prop :=
  ∃ g : R3 ≃ᵃⁱ[ℝ] R3, ∃ r : ℝ, 0 < r ∧ Q = (fun x => r • x) '' (g '' P)

/-- Coordinates outside `S` vanish on `face b S`. -/
lemma coord_eq_zero_of_mem_face {S : Finset ι} {x : E} (hx : x ∈ face b S) {i : ι}
    (hi : i ∉ S) : b.coord i x = 0

/-- Sign of `p + q√5` for integers `p, q`; `2` flags the impossible case `p² = 5q² ≠ 0`. -/
def sgnPQ (p q : Int) : Int :=
  if p = 0 ∧ q = 0 then 0
  else if 0 ≤ p ∧ 0 ≤ q then 1
  else if p ≤ 0 ∧ q ≤ 0 then -1
  else if 0 < p then (if 5 * q * q < p * p then 1 else if p * p < 5 * q * q then -1 else 2)
  else (if p * p < 5 * q * q then 1 else if 5 * q * q < p * p then -1 else 2)

/-- Cross product. -/
def cross (u v : V) : V :=
  ⟨u.y * v.z - u.z * v.y, u.z * v.x - u.x * v.z, u.x * v.y - u.y * v.x⟩
